bindings.expression:
{(e) => {
                  const file = e.target.files?.[0];
                  if (file) onAttach(file);
                  e.target.value = "";
                }}

{(event) => {
        const node = event.currentTarget;
        pinnedToBottom.current = node.scrollHeight - node.scrollTop - node.clientHeight < 80;
        setShowJumpToLatest(!pinnedToBottom.current);
      }}

{() => {
        pinnedToBottom.current = true;
        setShowJumpToLatest(false);
        bottomRef.current?.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth" });
      }}

{() => {
                  setRemoving(true);
                  setRemoveError(null);
                  void onRemove(doc.id)
                    .then(() => setShowConfirm(false))
                    .catch((error) => setRemoveError(error instanceof Error ? error.message : "Could not remove this document."))
                    .finally(() => setRemoving(false));
                }}

{(event) => {
                        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
                        event.preventDefault();
                        const tabs: MemoryTab[] = ["all", "source-docs", "communications"];
                        const direction = event.key === "ArrowRight" ? 1 : -1;
                        const next = tabs[(tabs.indexOf(tab) + direction + tabs.length) % tabs.length];
                        setActiveTab(next);
                        const buttons = event.currentTarget.closest("[role='tablist']")?.querySelectorAll<HTMLElement>("[role='tab']");
                        buttons?.[tabs.indexOf(next)]?.focus();
                      }}

{(event) => {
                  if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
                  event.preventDefault();
                  const next = panel === "memory" ? "timeline" : "memory";
                  selectPanel(next);
                  event.currentTarget.parentElement?.querySelector<HTMLElement>(`[role="tab"]:nth-of-type(${next === "memory" ? 1 : 2})`)?.focus();
                }}

{(e) => {
                if (e.key === "Enter") void handleNameSave();
                if (e.key === "Escape") {
                  setNameValue(workspace.name);
                  setEditingName(false);
                }
              }}

{() => void execute(composer, {
            ...(composer === "request_clarification" ? { note } : {}),
            ...(composer === "defer" ? { until: new Date(until).toISOString() } : {})
          })}

{() => {
                    const mode = composer.mode;
                    if (!mode) return;
                    const action: TruthInboxAction = mode === "clarification" ? "request_clarification" : mode;
                    void execute(item, action, {
                      ...(mode === "clarification" || mode === "dismiss" ? { note } : {}),
                      ...(mode === "defer" || mode === "snooze" ? { until: new Date(until).toISOString() } : {})
                    });
                  }}
